WITH base AS (SELECT *, CASE WHEN budget >= 3069000 THEN 'High' WHEN budget >= 1706000 THEN 'Medium' ELSE 'Low' END budget_tier, CASE WHEN budget >= 4219000 THEN 'High' WHEN budget >= 1124000 THEN 'Medium' ELSE 'Low' END budget_band FROM departments WHERE location = 'Berlin') SELECT id, dept_name, location, budget, budget_tier, budget_band, LAST_VALUE(location, TRUE) OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_location, NTILE(10) OVER w_hist budget_bucket FROM base WINDOW w_hist AS (PARTITION BY location, dept_name ORDER BY budget DESC, id)
